168	func listDeleteUserAttachments(ctx context.Context, tx *sql.Tx, userID int32, memoIDs []int32) ([]*store.Attachment, error) {
169		attachments := make([]*store.Attachment, 0)
170		seen := make(map[int32]struct{})
171		if err := appendDeleteUserAttachments(ctx, tx, `
172			SELECT
173				id,
174				uid,
175				creator_id,
176				memo_id,
177				storage_type,
178				reference,
179				payload
180			FROM attachment
181			WHERE creator_id = `+deleteUserPlaceholder(1), []any{userID}, seen, &attachments); err != nil {
182			return nil, err
183		}
184	
185		for _, batch := range deleteUserBatches(memoIDs, deleteUserBatchSize) {
186			clause, args := deleteUserInClause(1, batch)
187			if err := appendDeleteUserAttachments(ctx, tx, `
188				SELECT
189					id,
190					uid,
191					creator_id,
192					memo_id,
193					storage_type,
194					reference,
195					payload
196				FROM attachment
197				WHERE memo_id IN `+clause, args, seen, &attachments); err != nil {
198				return nil, err
199			}
200		}
201	
202		return attachments, nil
203	}
204	
205	func appendDeleteUserAttachments(ctx context.Context, tx *sql.Tx, query string, args []any, seen map[int32]struct{}, attachments *[]*store.Attachment) error {
206		rows, err := tx.QueryContext(ctx, query, args...)
207		if err != nil {
208			return err
209		}
210		defer rows.Close()
211	
212		for rows.Next() {
213			attachment := &store.Attachment{}
214			var memoID sql.NullInt32
215			var storageType string
216			var payloadBytes []byte
217			if err := rows.Scan(&attachment.ID, &attachment.UID, &attachment.CreatorID, &memoID, &storageType, &attachment.Reference, &payloadBytes); err != nil {
218				return err
219			}
220			if _, exists := seen[attachment.ID]; exists {
221				continue
222			}
223			seen[attachment.ID] = struct{}{}
224			if memoID.Valid {
225				attachment.MemoID = &memoID.Int32
226			}
227			attachment.StorageType = storepb.AttachmentStorageType(storepb.AttachmentStorageType_value[storageType])
228			payload := &storepb.AttachmentPayload{}
229			if len(payloadBytes) > 0 {
230				if err := protojsonUnmarshaler.Unmarshal(payloadBytes, payload); err != nil {
231					return err
232				}
233			}
234			attachment.Payload = payload
235			*attachments = append(*attachments, attachment)
236		}
237		return rows.Err()
238	}
